  function _ext(name) { const m = /\.([^.]+)$/.exec(name || ''); return m ? m[1].toLowerCase() : ''; }
  function _skipModal(ext) {
    if (ext === 'glb' || ext === 'gltf') return true;
    try { return localStorage.getItem('import_skip_' + ext) === '1'; } catch (_) { return false; }
  }
