    const set = (id, t) => { const el = $s(id); if (el) el.textContent = t; };
    const bar = (id, f) => { const el = $s(id); if (el) el.style.width = (Math.max(0, Math.min(1, f || 0)) * 100).toFixed(1) + '%'; };
