    const before = (id, title) => { const row = $s(id)?.closest('.toggle, .field'); if (row) row.insertAdjacentHTML('beforebegin', _group(title)); };
    $s('set-viewport-extra').insertAdjacentHTML('beforebegin', _group('Overlays'));
