  const w = c.clientWidth, h = Math.max(1, c.clientHeight);
  // Both projections follow the aspect (orthographic keeps its vertical
  // extent and derives the horizontal one from it).
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
