        if (stopped()) { why = 'You stopped it.'; break; }
        let want = now.triangles;
        if (mbT > 0 && now.mb > mbT) want = Math.min(want, Math.floor(now.triangles * (mbT / now.mb) * 0.94));
        if (triT > 0) want = Math.min(want, Math.floor(triT * 0.97));
