    try { const n = g.index ? g.index.count / 3 : g.attributes.position.count / 3; const pp = _polyIds.get(o.geom); if (pp && pp.length === n) _polyIds.set(g, pp); if (_triOnly.has(o.geom)) _triOnly.add(g); } catch (_) {}
