    verts = fmtNum(p.vertCount);
    bbox  = _fmtDims(sz);
    diag  = _fmtLen(p.sizeMetrics.diag, 3);
    pct   = (p.sizeMetrics.diag / _liveSceneDiag() * 100).toFixed(2) + '%';
