    heroTris = tt; heroSub = triShareLabel; heroRight = '≈ ' + fmtNum(Math.round(tt / Math.max(1, ids.length))) + ' per part';
    for (const id of ids) { const q = getPart(id); if (q) heroWas += q._tris0 || q.triCount; }
