function _updateSelectedChip() {
  const el = $('sb-selected'); if (!el) return;
  const n = state.selected.size;
  $('sb-selected-n').textContent = n;
  el.classList.toggle('empty', n === 0);
  el.classList.toggle('active', n > 0);
}

