      d.x0strip = d.tabs[0].left;
      d.gap = Math.max(0, d.tabs[1].left - (d.tabs[0].left + d.tabs[0].width));
      d.end = d.tabs[d.tabs.length - 1].left + d.tabs[d.tabs.length - 1].width;
