const _safeModeAction = (primary) => ({ label: 'Safe mode', primary, run: () => { location.search = '?webgl=1&safe=1'; } });

// Safe mode (?safe=1): WebGL2 instead of WebGPU (?webgl=1), tiny parts skipped
