  $('sb-tris').textContent = fmtNum(totalTris);
  $('sb-verts').textContent = fmtNum(totalVerts);
  $('sb-mem').textContent = fmtBytes(totalBytes);
  $('vp-tris').textContent = fmtNum(totalTris);
  $('vp-parts').textContent = fmtNum(state.parts.length);
