  const esc = (t) => escapeHtml(String(t));
  const live = () => state.parts.filter(p => p && !p.deleted);
  const geomOf = (p) => (p.mesh && p.mesh.geometry) || (p.instancedMesh && p.instancedMesh.geometry) || null;

