    const eye = p.visible
      ? `<i data-lucide="eye"></i>`
      : `<i data-lucide="eye-off"></i>`;
    const inst = _instBadge(_liveShareCount(p));
    const lockIcon = p.locked ? `<span class="tree-lock" title="Locked">${_ico('lock')}</span>` : '';
    const triFrac = Math.log10(p.triCount + 1) / logMax;
