  const MODES = { loop: ['repeat', 'Loop: start again at the end'], pingpong: ['arrow-left-right', 'Ping-pong: turn round at each end'], once: ['arrow-right-to-line', 'Once: stop at the end'] }, NEXT = { loop: 'pingpong', pingpong: 'once', once: 'loop' };
