  if (e.target.closest('[data-toggle], .tree-vis, .tree-chev, .tree-expand, [data-act], button, input, select')) return;
  const row = e.target.closest('.tree-node');
  if (!row) return;
  if (row.classList.contains('is-hidden')) return;
