    add?.addEventListener('change', () => { o.add = add.checked; changed(); });
    pct?.addEventListener('change', () => { const v = parseFloat(pct.value); o.maxPct = isFinite(v) && v > 0 ? +Math.min(100, v).toFixed(2) : 0; changed(); });
